import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

// ⚠️ GEMINI API KEY (Burayı doldurduğundan emin ol)
const GEMINI_API_KEY = ""; 

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]);
  const [seciliMekanId, setSeciliMekanId] = useState(null);
  const [veriYukleniyor, setVeriYukleniyor] = useState(true);

  const [muzekartVar, setMuzekartVar] = useState(false);
  const [aiBilgi, setAiBilgi] = useState({ cevap: "", temp: "", durum: "" });
  const [loading, setLoading] = useState(false);
  const [tarihceBilgisi, setTarihceBilgisi] = useState({}); 

  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => {
        setMekanlar(data);
        setVeriYukleniyor(false);
      })
      .catch(err => {
        console.warn("Backend Hatası", err);
        setVeriYukleniyor(false);
      });
  }, []);

  const handleMouseEnter = async (m) => {
    if (m.kategori !== "Tarih") return;
    if (tarihceBilgisi[m.id]) return;

    try {
      const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });
      const prompt = `${m.ad} hakkında en fazla 15 kelimelik tarihi bilgi ver.`;
      const result = await model.generateContent(prompt);
      setTarihceBilgisi(prev => ({ ...prev, [m.id]: result.response.text() }));
    } catch (err) {
      setTarihceBilgisi(prev => ({ ...prev, [m.id]: "Hizmet şu an meşgul..." }));
    }
  };

  const rotayiHaritadaGoster = () => {
    if (favoriler.length === 0) return alert("Listeniz boş!");
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((position) => {
        const { latitude, longitude } = position.coords;
        const url = `https://www.google.com/maps/dir/?api=1&origin=$${latitude},${longitude}&destination=${encodeURIComponent(favoriler[favoriler.length - 1].ad)}&waypoints=${favoriler.slice(0, -1).map(m => encodeURIComponent(m.ad)).join('|')}&travelmode=driving`;
        window.open(url, '_blank');
      }, () => {
        window.open(`https://www.google.com/maps/dir/$${favoriler.map(m => encodeURIComponent(m.ad)).join('/')}`, '_blank');
      });
    }
  };

  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => f.id === mekan.id);
    if (varMi) setFavoriler(favoriler.filter(f => f.id !== mekan.id));
    else setFavoriler([...favoriler, mekan]);
  };

  const askSmartAI = async (mekan) => {
    if (seciliMekanId === mekan.id) { setSeciliMekanId(null); return; }
    setSeciliMekanId(mekan.id);
    setLoading(true);
    try {
      const wRes = await fetch(`http://localhost:5000/api/hava-durumu?lat=${mekan.lat}&lon=${mekan.lon}`);
      const wData = await wRes.json(); 
      const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });
      const result = await model.generateContent(`Antalya ${mekan.ad} için kısa ipucu.`);
      setAiBilgi({ cevap: result.response.text(), temp: wData.sicaklik, durum: wData.durum });
    } catch (err) { setAiBilgi({ cevap: "Hata!", temp: "--" }); } finally { setLoading(false); }
  };

  const kategoriler = {
    "Tarih": mekanlar.filter(m => m.kategori === "Tarih"),
    "Doğa": mekanlar.filter(m => m.kategori === "Doğa"),
    "Eğlence": mekanlar.filter(m => m.kategori === "Eğlence"),
    "Dalış": mekanlar.filter(m => m.kategori === "Dalış"),
    "Tekne": mekanlar.filter(m => m.kategori === "Tekne"),
    "Yemek": mekanlar.filter(m => m.kategori === "Yemek"),
  };

  return (
    <div style={{ fontFamily: "'Poppins', sans-serif", background: '#000', color: '#fff' }}>
      <style>{`
        html { scroll-behavior: smooth; }
        .navbar { display: flex; justify-content: space-between; align-items: center; padding: 15px 40px; background: rgba(0, 0, 0, 0.9); position: sticky; top: 0; z-index: 1000; border-bottom: 1px solid rgba(255,255,255,0.1); }
        .nav-link { color: #cbd5e1; text-decoration: none; font-size: 13px; font-weight: 600; padding: 8px 20px; border: 1px solid rgba(255, 255, 255, 0.15); border-radius: 50px; transition: 0.3s; }
        .nav-link:hover { color: #fff; border-color: #f97316; }
        .category-section { min-height: 100vh; padding: 60px 40px; position: relative; background-size: cover; background-attachment: fixed; }
        .overlay { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0, 0, 0, 0.75); }
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 30px; position: relative; z-index: 2; }

        .card { background: rgba(30, 41, 59, 0.85); border-radius: 20px; overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.1); transition: 0.4s; }

        /* 🛠️ DÜZELTİLEN KISIM: SADECE RESMİN ÜSTÜNE BİNSİN */
        .img-container { position: relative; height: 200px; overflow: hidden; }
        .history-overlay {
            position: absolute; top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(15, 23, 42, 0.9);
            color: #f1f5f9; padding: 15px;
            display: flex; flex-direction: column; justify-content: center;
            opacity: 0; transition: opacity 0.4s ease;
            z-index: 5; pointer-events: none; /* Altındaki butonlara tıklamayı engellemez */
        }
        .card:hover .history-overlay { opacity: 1; }
        .btn-gradient { background: linear-gradient(135deg, #f97316 0%, #fb923c 100%); color: white; border: none; padding: 10px 25px; border-radius: 50px; font-weight: bold; cursor: pointer; }
      `}</style>

      <nav className="navbar">
        <div style={{ display:'flex', alignItems:'center', gap:'10px' }}>
            <span style={{fontSize:'28px'}}>🏝️</span>
            <div><div style={{ fontWeight: 800, color: '#38bdf8' }}>ANTALYA</div><div style={{ color: '#f97316', fontSize: '11px' }}>ROTA ASİSTANI</div></div>
        </div>
        <div style={{ display: 'flex', gap: '10px' }}>
          {Object.keys(kategoriler).map(k => <a key={k} href={`#${k}`} className="nav-link">{k}</a>)}
        </div>
        <button onClick={rotayiHaritadaGoster} className="btn-gradient">Rotayı Çiz 🚀</button>
      </nav>

      {Object.keys(kategoriler).map((kat) => (
        <div key={kat} id={kat} className="category-section" style={{ backgroundImage: `url(https://images.unsplash.com/photo-1528164344705-475426870763?q=80&w=2070)` }}>
            <div className="overlay"></div>
            <div style={{position:'relative', zIndex: 2}}>
                <h2 style={{borderLeft: '6px solid #f97316', paddingLeft: '20px', marginBottom: '30px'}}>{kat} Rotaları</h2>
                <div className="grid">
                    {kategoriler[kat].map(m => (
                        <div key={m.id} className="card" onMouseEnter={() => handleMouseEnter(m)}>
                            <div className="img-container">
                                {kat === "Tarih" && (
                                  <div className="history-overlay">
                                    <h5 style={{color: '#f97316', margin: '0 0 5px 0'}}>🏛️ Tarihçe</h5>
                                    <p style={{fontSize: '12px', margin: 0}}>
                                      {tarihceBilgisi[m.id] || "Yükleniyor..."}
                                    </p>
                                  </div>
                                )}
                                <img src={m.resim} alt={m.ad} style={{width:'100%', height:'100%', objectFit:'cover'}} />
                            </div>

                            <div style={{padding: '20px'}}>
                                <div style={{display:'flex', justifyContent:'space-between', marginBottom:'10px'}}>
                                    <h3 style={{margin:0}}>{m.ad}</h3>
                                    <span style={{color: '#f97316', fontWeight:'bold'}}>{m.ucret} ₺</span>
                                </div>
                                <p style={{fontSize:'13px', color:'#94a3b8'}}>{m.aciklama}</p>
                                <div style={{ display: 'flex', gap: '10px', marginTop:'15px' }}>
                                    <button onClick={() => askSmartAI(m)} style={{flex:1, padding:'10px', borderRadius:'8px', border:'none', background:'#334155', color:'#38bdf8', cursor:'pointer'}}>✨ AI İpucu</button>
                                    <button onClick={() => toggleFavori(m)} style={{flex:1, padding:'10px', borderRadius:'8px', border:'none', background: favoriler.some(f=>f.id===m.id) ? '#ef4444' : '#0f766e', color:'white', cursor:'pointer'}}>
                                        {favoriler.some(f=>f.id===m.id) ? "Çıkar" : "Ekle +"}
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
      ))}
    </div>
  );
}

export default App;
